    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 94-year-old male named Albert with isolated systolic hypertension is started on amlodipine 5 mg daily. After 12 months, he reports bilateral lower-extremity ankle edema. His BP is now 138/72 mmHg. Renal function and albumin are normal. What is the mechanism of CCB-induced peripheral edema, and what is the most appropriate management?', '["The edema indicates decompensated heart failure caused by the CCB; discontinue amlodipine immediately and start intravenous dobutamine", "CCBs cause allergic angioedema; switch to an ACE inhibitor immediately and administer epinephrine", "Dihydropyridine CCBs cause preferential dilation of precapillary arterioles without proportional dilation of postcapillary venules, creating a hydrostatic pressure gradient that forces fluid into the interstitial space; adding an ACE inhibitor or ARB (which dilates the postcapillary venules) can counterbalance this effect and reduce the edema", "CCB-induced edema is caused by renal sodium retention and should be treated by adding a loop diuretic and restricting sodium to < 500 mg/day", "This is a normal gravitational effect of aging; no treatment adjustment is needed as long as BP is controlled"]'::jsonb, 2, '**Dihydropyridine CCB-induced peripheral edema** (amlodipine, nifedipine) is a common dose-dependent side effect affecting 5-30% of patients. The mechanism is **NOT fluid retention** (renal); it is a **hemodynamic redistribution** effect: DHP-CCBs preferentially dilate **precapillary arterioles** without proportional dilation of **postcapillary venules**. This increases the **capillary hydrostatic pressure gradient**, forcing plasma into the interstitial space (dependent edema). Management: (1) **Add an ACE inhibitor or ARB** — these agents dilate the postcapillary venules, restoring the arteriolar-venular balance and reducing the hydrostatic gradient (combination therapy reduces edema by 50-75%), (2) Dose reduction, (3) Switch to a non-DHP CCB or alternative class. (Ref: Hazzard''s Ch. 37; Sica DA, Clin Ther 2003; UWorld Step 2 CK)'),
    (v_topic_id, 'A 78-year-old male named Thomas with isolated systolic hypertension is started on amlodipine 5 mg daily. After 6 months, he reports bilateral lower-extremity ankle edema. His BP is now 138/68 mmHg. Renal function and albumin are normal. What is the mechanism of CCB-induced peripheral edema, and what is the most appropriate management?', '["This is a normal gravitational effect of aging; no treatment adjustment is needed as long as BP is controlled", "CCB-induced edema is caused by renal sodium retention and should be treated by adding a loop diuretic and restricting sodium to < 500 mg/day", "CCBs cause allergic angioedema; switch to an ACE inhibitor immediately and administer epinephrine", "The edema indicates decompensated heart failure caused by the CCB; discontinue amlodipine immediately and start intravenous dobutamine", "Dihydropyridine CCBs cause preferential dilation of precapillary arterioles without proportional dilation of postcapillary venules, creating a hydrostatic pressure gradient that forces fluid into the interstitial space; adding an ACE inhibitor or ARB (which dilates the postcapillary venules) can counterbalance this effect and reduce the edema"]'::jsonb, 4, '**Dihydropyridine CCB-induced peripheral edema** (amlodipine, nifedipine) is a common dose-dependent side effect affecting 5-30% of patients. The mechanism is **NOT fluid retention** (renal); it is a **hemodynamic redistribution** effect: DHP-CCBs preferentially dilate **precapillary arterioles** without proportional dilation of **postcapillary venules**. This increases the **capillary hydrostatic pressure gradient**, forcing plasma into the interstitial space (dependent edema). Management: (1) **Add an ACE inhibitor or ARB** — these agents dilate the postcapillary venules, restoring the arteriolar-venular balance and reducing the hydrostatic gradient (combination therapy reduces edema by 50-75%), (2) Dose reduction, (3) Switch to a non-DHP CCB or alternative class. (Ref: H